function serveInfoBook(request) {
  const url = new URL(request.url);

  if (url.pathname !== "/") {
    return new Response("Not Found", {
      status: 404,
      headers: {
        "content-type": "text/plain; charset=UTF-8",
        "x-content-type-options": "nosniff"
      }
    });
  }

  if (request.method !== "GET" && request.method !== "HEAD") {
    return new Response("Method Not Allowed", {
      status: 405,
      headers: {
        allow: "GET, HEAD",
        "content-type": "text/plain; charset=UTF-8",
        "x-content-type-options": "nosniff"
      }
    });
  }

  const body = request.method === "HEAD" ? null : INFO_BOOK;

  return new Response(body, {
    status: 200,
    headers: {
      "cache-control": "no-cache",
      "content-type": "text/plain; charset=UTF-8",
      "x-content-type-options": "nosniff"
    }
  });
}

// Keep this named export: the existing Durable Object binding uses this class.
export class EternalGateway extends DurableObject {
  async fetch(request) {
    return serveInfoBook(request);
  }
}

export default {
  async fetch(request, env, ctx) {
    return serveInfoBook(request);
  }
};
